import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { decodeDiskUsageTree } from "../src/features/diskUsage/diskUsageTreeFacts.ts";
import { diskUsageTilePixelArea, fullDiskUsageView, layoutDiskUsageTree } from "../src/features/diskUsage/diskUsageTreemapLayout.ts";
import { diskTreeBuffer } from "./diskUsageTreeFixture.ts";

// Original HEAD C# float32 layout, generated by the retained GeometryOracle source.
const cases = JSON.parse(readFileSync(new URL("./fixtures/diskUsageGeometryBoundary.json", import.meta.url), "utf8"));
let compared = 0;
for (const item of cases) {
  const tree = decodeDiskUsageTree(diskTreeBuffer([
    {id:0,parent:-1,size:item.total,name:"root",directory:true},
    {id:1,parent:0,size:item.total-1,name:"large",directory:false},
    {id:2,parent:0,size:1,name:"tiny",directory:false}
  ]))!;
  const layout = layoutDiskUsageTree(tree, 0, item.view);
  assert.deepEqual([...layout.nodeIds], item.tiles.map((tile: {id:number})=>tile.id), JSON.stringify(item));
  assert.equal(layout.omittedCount, item.omitted);
  for (let index=0;index<item.tiles.length;index++) {
    const expected=item.tiles[index];
    for (const [column,key] of [[layout.x,"x"],[layout.y,"y"],[layout.width,"w"],[layout.height,"h"]] as const) {
      assert.equal(column[index],Math.fround(expected[key]), `float32 ${key}, ${JSON.stringify(item)}`);
    }
  }
  compared++;
}
assert.equal(compared,144);
const atThreshold={...fullDiskUsageView,pixelWidth:64,pixelHeight:64};
assert.equal(diskUsageTilePixelArea(1/512,1,atThreshold),8);
assert.ok(diskUsageTilePixelArea(1/513,1,atThreshold)<8);
assert.ok(diskUsageTilePixelArea(1/511,1,atThreshold)>8);

// A partial page keeps the authoritative sibling total; it never fills missing bytes with
// larger apparent tiles. The context on later pages is also visibly incomplete.
const pageOne=decodeDiskUsageTree(diskTreeBuffer([
  {id:0,parent:-1,size:100,name:"root",directory:true,childTotal:100,firstChild:1},
  {id:1,parent:0,size:20,name:"first",directory:false,nextSibling:2}
],"C:\\",2))!;
const partial=layoutDiskUsageTree(pageOne);
assert.equal(partial.nextCursorNodeId,2);
assert.equal(partial.subtreeComplete[0],0);
assert.equal(partial.subtreeComplete[1],1);
assert.ok(Math.abs(partial.width[1]*partial.height[1]-.2)<1e-6);
const pageTwo=decodeDiskUsageTree(diskTreeBuffer([
  {id:0,parent:-1,size:100,name:"root",directory:true,childTotal:100,firstChild:1},
  {id:2,parent:0,size:80,name:"second",directory:false}
]))!;
assert.equal(pageTwo.subtreeComplete[0],0);
assert.equal(pageTwo.nextCursorNodeId,-1);
assert.ok(Math.abs(layoutDiskUsageTree(pageTwo).width[1]*layoutDiskUsageTree(pageTwo).height[1]-.8)<1e-6);

// B4: count allocations made by the actual production function, after the page index exists.
const largeNodes=Array.from({length:400002},(_,index)=>({
  id:index,parent:index===0 ? -1 : index===400001 ? 400000 : 0,
  size:index===0 ? 400000 : 1,name:"",directory:index===0||index===400000
}));
const large=decodeDiskUsageTree(diskTreeBuffer(largeNodes))!;
assert.equal(large.subtreeNodeCounts[400000],2);
const globals=globalThis as unknown as Record<string,unknown>;
const originals=new Map<string,unknown>();
let workingBytes=0,largestArray=0;
for (const name of ["Int32Array","Uint32Array","Uint8Array","Float32Array","Float64Array"]) {
  const Native=globals[name] as typeof Float64Array;
  originals.set(name,Native);
  globals[name]=new Proxy(Native,{construct(target,args) {
    if (typeof args[0]==="number") {workingBytes+=args[0]*Native.BYTES_PER_ELEMENT;largestArray=Math.max(largestArray,args[0]);}
    return Reflect.construct(target,args);
  }});
}
try {
  for (let attempt=0;attempt<20;attempt++) {
    workingBytes=0;largestArray=0;
    const layout=layoutDiskUsageTree(large,400000,{...fullDiskUsageView,scale:attempt+1});
    assert.equal(layout.nodeIds.length,2);
    assert.equal(largestArray,2);
    assert.equal(workingBytes,100);
  }
} finally {for (const [name,Native] of originals) globals[name]=Native;}
console.log(JSON.stringify({geometryCases:compared,float32Differences:0,tinySubtreeTiles:2,layouts:20,workingArrayBytesPerLayout:100,largestWorkingArray:largestArray}));
